# 가짜 LLM 과 가짜 환경으로 돌려 보는 최소 ReAct 루프
WORLD = {"찬장 1": ["꽃병"], "조리대 3": ["사과", "후추통"], "서랍 1": []}
hand = []

def env(action, arg):                      # 환경: 행동을 받아 관찰을 돌려준다
    if action == "look":
        return f"{arg}에는 {WORLD[arg] or '아무것도 없다'}"
    if action == "take":
        WORLD["조리대 3"].remove(arg); hand.append(arg); return f"{arg}을 집었다"
    if action == "put":
        WORLD[arg].append(hand.pop()); return f"{arg}에 넣었다"

def fake_llm(memory):                      # LLM 코어 흉내: 기록을 보고 다음 생각·행동
    seen = " ".join(memory)
    if "후추통을 집었다" in seen:
        return "이제 서랍에 넣자", ("put", "서랍 1")
    if "후추통" in seen:
        return "조리대 3에 있다, 집자", ("take", "후추통")
    if "찬장 1" in seen:
        return "찬장엔 없다, 조리대를 보자", ("look", "조리대 3")
    return "찬장에 있을 것 같다", ("look", "찬장 1")

memory = []                                # 메모리: 지금까지의 궤적
for step in range(6):
    thought, (act, arg) = fake_llm(memory)  # 계획·추론
    obs = env(act, arg)                    # 도구로 행동 → 환경이 관찰 반환
    memory += [f"생각:{thought}", f"관찰:{obs}"]
    print(step, thought, "|", act, arg, "->", obs)
    if "서랍 1에 넣었다" in obs:
        break

import math, time

class Memory:
    def __init__(self):
        self.items = []                         # 일화 기억: 원시 기록 그대로
        self.skills = {}                        # 절차 기억: 이름 -> 실행 가능한 함수

    def add(self, text, importance, t=None):
        self.items.append(dict(text=text, imp=importance / 10, t=t or time.time()))

    def retrieve(self, query, now, k=2):
        def rel(text):                          # 관련성: 단어 겹침(실제로는 임베딩 코사인)
            a, b = set(text.split()), set(query.split())
            return len(a & b) / math.sqrt(len(a) * len(b))
        def score(m):
            rec = 0.995 ** ((now - m["t"]) / 3600)
            return rec + m["imp"] + rel(m["text"])
        return sorted(self.items, key=score, reverse=True)[:k]

    def summarize(self):                        # 의미 기억: 궤적을 짧게(실제로는 LLM 요약)
        return " / ".join(m["text"] for m in self.items if m["imp"] >= 0.5)

now = time.time()
mem = Memory()
mem.add("침대 정리 했다", 1, now - 3600)
mem.add("발렌타인 파티 계획 중", 8, now - 7200)
mem.add("파티 장식 준비", 5, now - 600)
print([m["text"] for m in mem.retrieve("기대하는 파티 계획", now)])
print(mem.summarize())
mem.skills["make_table"] = lambda: "나무 4개로 작업대 제작"   # Voyager 식 스킬 저장
print(mem.skills["make_table"]())

import re

TOOLS = {
    "Calculator": lambda expr: f"{eval(expr, {'__builtins__': {}}):.2f}",
    "MT":         lambda w: {"tortuga": "turtle"}.get(w, "?"),
    "QA":         lambda q: "Massachusetts Medical Society",
}

def fill_tool_calls(text):
    """Toolformer 식 [도구(인자)] 표시를 찾아 실제로 호출하고 결과를 끼워 넣는다."""
    def run(m):
        name, arg = m.group(1), m.group(2).strip('"')
        return f"[{name}({arg}) -> {TOOLS[name](arg)}]"
    return re.sub(r"\[(\w+)\((.*?)\)\]", run, text)

draft = '1400명 중 400명 [Calculator(400/1400)] 이 통과했다. tortuga 는 [MT("tortuga")] 라는 뜻이다.'
print(fill_tool_calls(draft))

import math
from collections import Counter

DOCS = [
    "위산과 단백질 분해 효소가 삼킨 병원체를 막는다",
    "소장은 영양분을 흡수한다",
    "간은 해독 작용을 한다",
]

def vec(text):
    return Counter(text.split())

def cos(a, b):
    dot = sum(a[w] * b[w] for w in a)
    return dot / (math.sqrt(sum(v * v for v in a.values())) * math.sqrt(sum(v * v for v in b.values())) or 1)

def rag(question, k=1):
    q = vec(question)
    top = sorted(DOCS, key=lambda d: cos(q, vec(d)), reverse=True)[:k]   # 1. 검색
    prompt = "참고:\n" + "\n".join(top) + f"\n질문: {question}"            # 2. 보강
    return prompt                                                          # 3. 생성은 LLM(prompt)

print(rag("위에서 병원체 감염을 막는 것은"))
